defined('_JEXEC') or die;
use Joomla\CMS\Factory; use Joomla\CMS\Language\Text; use Joomla\CMS\MVC\View\HtmlView as BaseHtmlView; use Joomla\CMS\Toolbar\ToolbarHelper;
final class HtmlView extends BaseHtmlView { public array $items=[]; public array $organizations=[]; public array $people=[]; public array $obligations=[]; public function display($tpl=null):void { if(!Factory::getApplication()->getIdentity()->authorise('core.manage','com_decarofinance')) throw new \RuntimeException(Text::_('JERROR_ALERTNOAUTHOR'),403); ToolbarHelper::title(Text::_('COM_DECAROFINANCE_PAYMENTS'),'credit'); \Xdecaro\Component\Decarofinance\Administrator\Helper\UiHelper::loadAssets(); $component=Factory::getApplication()->bootComponent('com_decarofinance'); if(!$component instanceof \Xdecaro\Component\Decarofinance\Administrator\Extension\DecarofinanceComponent) throw new \RuntimeException('Finance component is unavailable.'); $query=$component->getFinanceQueryService(); $references=$component->getReferenceLookupService(); $this->items=$query->listPayments(); foreach($this->items as &$item){$item['payer_label']=$references->label($item['payer_component']??null,$item['payer_entity']??null,$item['payer_id']??null);} unset($item); $this->organizations=$references->listOrganizations(); $this->people=$references->listPeople(); $this->obligations=array_values(array_filter($query->listObligations(),static fn(array $row):bool=>in_array((string)($row['status']??''),['open','partial'],true))); parent::display($tpl); } }
